class HistoryMap:
    def __init__(self):
        self.history = {}                    # key -> list of (time, value)

    def set(self, key: str, value: str, time: int) -> None:
        self.history.setdefault(key, []).append((time, value))

    def get(self, key: str, time: int) -> str | None:
        for t, value in reversed(self.history.get(key, [])):
            if t <= time:
                return value
        return None


def run_history(ops: list[list]) -> list:
    store = HistoryMap()
    return [getattr(store, name)(*args) for name, *args in ops]
